import pyomo.environ as pyo

DATA = {
    "foods": ["Beef", "Pasta", "Broccoli", "Chicken", "Apple",
              "Pork", "Lentils", "Eggs", "Cheese"],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per serving ($)
    "cost": {
        "Beef": 5, "Pasta": 6, "Broccoli": 5, "Chicken": 4, "Apple": 1,
        "Pork": 6, "Lentils": 1, "Eggs": 2, "Cheese": 7,
    },
    # protein grams per serving
    "protein": {
        "Beef": 18, "Pasta": 2, "Broccoli": 7, "Chicken": 20, "Apple": 5,
        "Pork": 13, "Lentils": 15, "Eggs": 20, "Cheese": 9,
    },
    # carbohydrate grams per serving
    "carbs": {
        "Beef": 13, "Pasta": 25, "Broccoli": 30, "Chicken": 16, "Apple": 6,
        "Pork": 9, "Lentils": 18, "Eggs": 18, "Cheese": 14,
    },
    # calories per serving
    "calories": {
        "Beef": 233, "Pasta": 251, "Broccoli": 191, "Chicken": 231, "Apple": 111,
        "Pork": 275, "Lentils": 99, "Eggs": 210, "Cheese": 74,
    },
    # minimum daily requirements
    "req_protein": 68,
    "req_carbs": 151,
    "req_calories": 1900,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["foods"])

    model.x = pyo.Var(model.I, within=pyo.NonNegativeReals,
                      bounds=(0, None))

    def cost_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)
    model.obj = pyo.Objective(expr=cost_rule, sense=pyo.minimize)

    def protein_rule(m):
        return sum(d["protein"][i] * m.x[i] for i in m.I) >= d["req_protein"]
    model.protein_requirement = pyo.Constraint(rule=protein_rule)

    def carbs_rule(m):
        return sum(d["carbs"][i] * m.x[i] for i in m.I) >= d["req_carbs"]
    model.carbs_requirement = pyo.Constraint(rule=carbs_rule)

    def calories_rule(m):
        return sum(d["calories"][i] * m.x[i] for i in m.I) >= d["req_calories"]
    model.calories_requirement = pyo.Constraint(rule=calories_rule)

    return model


